    await $.command.register({
      name: 'progress-clear',
      description: 'Clear the progress line above the prompt',
    })
    setSpeed($, false)

    return next(e)
  })

  on('command.run', { command: 'progress-clear' }, async $ => {
    clearBatch(await listAgents($))
    tasks.clear()
    await update($, view, () => null)

    return { text: 'Progress line cleared.' }
  })

