    const ran = await next(e)
    if (e.agentId === undefined && ran.deny === undefined && !ran.isError) {
      if (e.status === 'deleted') tasks.delete(e.taskId)
      else if (e.status) tasks.set(e.taskId, e.status)
      void refresh($)
    }

    return ran
  })

