    const ran = await next(e)
    if (e.agentId === undefined && ran.deny === undefined && !ran.isError) {
      todos = e.todos.map(t => t.status)
      void refresh($)
    }

    return ran
  })

  on('agent.spawn', async ($, e, next) => {
    const ran = await next(e)
    setSpeed($, true)

    return ran
  })

